INSERT INTO `email_templates` (`id`, `key`, `name`, `subject`, `body_html`, `available_variables`, `is_active`, `send_copy_to_admin`, `created_at`, `updated_at`) VALUES (1,'donation.thank_you','Donation thank-you','Thank you for your donation — receipt {{ receipt_number }}','<h1 style=\"font-size: 18px; margin: 0 0 16px;\">Thank you for your donation</h1>\n<p style=\"font-size: 14px; line-height: 1.6;\">Hi {{ donor_name }},</p>\n<p style=\"font-size: 14px; line-height: 1.6;\">Your donation of ₹{{ amount }} means a lot to us. Your receipt (<strong>{{ receipt_number }}</strong>) is attached to this email.</p>','[\"donor_name\", \"amount\", \"receipt_number\", \"org_name\"]',1,0,'2026-08-03 04:31:01','2026-08-03 04:31:01'),(2,'donation.receipt','Donation receipt attached','Your receipt {{ receipt_number }} is attached','<p style=\"font-size: 14px; line-height: 1.6;\">Hi {{ donor_name }},</p>\n<p style=\"font-size: 14px; line-height: 1.6;\">Your receipt <strong>{{ receipt_number }}</strong> for ₹{{ amount }} is attached to this email.</p>','[\"donor_name\", \"amount\", \"receipt_number\", \"org_name\"]',1,0,'2026-08-03 04:31:01','2026-08-03 04:31:01'),(3,'donation.failed','Donation payment failed','We couldn\'t process your donation','<p style=\"font-size: 14px; line-height: 1.6;\">Hi {{ donor_name }},</p>\n<p style=\"font-size: 14px; line-height: 1.6;\">Your donation of ₹{{ amount }} could not be processed. No amount was charged — please try again whenever you\'re ready.</p>','[\"donor_name\", \"amount\", \"org_name\"]',1,0,'2026-08-03 04:31:01','2026-08-03 04:31:01'),(4,'receipt.80g','80G receipt issued','Your 80G receipt {{ receipt_number }}','<p style=\"font-size: 14px; line-height: 1.6;\">Hi {{ donor_name }},</p>\n<p style=\"font-size: 14px; line-height: 1.6;\">Your 80G tax-exemption receipt <strong>{{ receipt_number }}</strong> is attached to this email.</p>','[\"donor_name\", \"receipt_number\", \"org_name\"]',1,0,'2026-08-03 04:31:01','2026-08-03 04:31:01'),(5,'subscription.activated','Monthly donation activated','Your monthly donation is set up','<h1 style=\"font-size: 18px; margin: 0 0 16px;\">Your monthly donation is set up</h1>\n<p style=\"font-size: 14px; line-height: 1.6;\">Hi {{ donor_name }},</p>\n<p style=\"font-size: 14px; line-height: 1.6;\">Thank you — your monthly donation of ₹{{ amount }} is now active. Your next charge is on {{ next_charge_date }}.</p>\n<p style=\"font-size: 14px; line-height: 1.6;\">You can view, pause, or cancel this any time from your donor portal.</p>','[\"donor_name\", \"amount\", \"next_charge_date\", \"org_name\"]',1,0,'2026-08-03 04:31:01','2026-08-03 04:31:01'),(6,'subscription.charged','Monthly donation charged','Your monthly donation was successful','<p style=\"font-size: 14px; line-height: 1.6;\">Hi {{ donor_name }},</p>\n<p style=\"font-size: 14px; line-height: 1.6;\">This month\'s donation of ₹{{ amount }} went through — thank you for your continued support.</p>','[\"donor_name\", \"amount\", \"org_name\"]',1,0,'2026-08-03 04:31:01','2026-08-03 04:31:01'),(7,'subscription.charge_failed','Monthly donation charge failed','We couldn\'t process this month\'s donation','<p style=\"font-size: 14px; line-height: 1.6;\">Hi {{ donor_name }},</p>\n<p style=\"font-size: 14px; line-height: 1.6;\">This month\'s donation of ₹{{ amount }} could not be processed ({{ reason }}). This usually happens on the bank\'s side — please check your payment method is still valid, or update it any time from your portal.</p>','[\"donor_name\", \"amount\", \"reason\", \"org_name\"]',1,0,'2026-08-03 04:31:01','2026-08-03 04:31:01'),(8,'subscription.halted','Monthly donation halted','Your monthly donation has been paused','<p style=\"font-size: 14px; line-height: 1.6;\">Hi {{ donor_name }},</p>\n<p style=\"font-size: 14px; line-height: 1.6;\">After a few unsuccessful attempts, we\'ve paused your monthly donation of ₹{{ amount }}. No further charges will happen automatically — reach out any time to restart it.</p>','[\"donor_name\", \"amount\", \"org_name\"]',1,0,'2026-08-03 04:31:01','2026-08-03 04:31:01'),(9,'subscription.cancelled','Monthly donation cancelled','Your monthly donation has been cancelled','<p style=\"font-size: 14px; line-height: 1.6;\">Hi {{ donor_name }},</p>\n<p style=\"font-size: 14px; line-height: 1.6;\">Your monthly donation of ₹{{ amount }} has been cancelled. Thank you for everything you\'ve given so far.</p>','[\"donor_name\", \"amount\", \"org_name\"]',1,0,'2026-08-03 04:31:01','2026-08-03 04:31:01'),(10,'member.welcome','Member account created','Welcome to {{ org_name }}','<p style=\"font-size: 14px; line-height: 1.6;\">Hi {{ member_name }},</p>\n<p style=\"font-size: 14px; line-height: 1.6;\">Your member account is ready. Sign in to your portal any time to view your documents and donation history.</p>','[\"member_name\", \"org_name\"]',1,0,'2026-08-03 04:31:01','2026-08-03 04:31:01'),(11,'member.id_card_issued','Member ID card issued','Your member ID card — {{ document_number }}','<p style=\"font-size: 14px; line-height: 1.6;\">Hi {{ member_name }},</p>\n<p style=\"font-size: 14px; line-height: 1.6;\">Your member ID card (<strong>{{ document_number }}</strong>) is ready — you can download it any time from your portal.</p>','[\"member_name\", \"document_number\", \"org_name\"]',1,0,'2026-08-03 04:31:01','2026-08-03 04:31:01'),(12,'member.appointment_letter','Appointment letter issued','Your appointment letter — {{ document_number }}','<p style=\"font-size: 14px; line-height: 1.6;\">Hi {{ member_name }},</p>\n<p style=\"font-size: 14px; line-height: 1.6;\">Your appointment letter (<strong>{{ document_number }}</strong>) is ready — you can download it any time from your portal.</p>','[\"member_name\", \"document_number\", \"org_name\"]',1,0,'2026-08-03 04:31:01','2026-08-03 04:31:01'),(13,'member.certificate_issued','Certificate issued','Your certificate — {{ document_title }}','<p style=\"font-size: 14px; line-height: 1.6;\">Hi {{ member_name }},</p>\n<p style=\"font-size: 14px; line-height: 1.6;\">Your certificate \"{{ document_title }}\" (<strong>{{ document_number }}</strong>) is ready — you can download it any time from your portal.</p>','[\"member_name\", \"document_number\", \"document_title\", \"org_name\"]',1,0,'2026-08-03 04:31:01','2026-08-03 04:31:01'),(14,'notice.default','Notice email wrapper','{{ notice_title }}','<h1 style=\"font-size: 18px; margin: 0 0 16px;\">{{ notice_title }}</h1>\n{{ notice_body }}\n<p style=\"font-size: 13px; margin-top: 16px;\"><a href=\"{{ portal_url }}\">View in your portal</a></p>','[\"notice_title\", \"notice_body\", \"portal_url\", \"org_name\"]',1,0,'2026-08-03 04:31:01','2026-08-03 04:31:01'),(15,'campaign.update','Campaign update published','Update on {{ campaign_title }}','<h1 style=\"font-size: 18px; margin: 0 0 16px;\">{{ update_title }}</h1>\n<p style=\"font-size: 14px; line-height: 1.6;\">Hi {{ donor_name }},</p>\n{{ update_body }}','[\"donor_name\", \"campaign_title\", \"update_title\", \"update_body\", \"org_name\"]',1,0,'2026-08-03 04:31:01','2026-08-03 04:31:01'),(16,'fundraiser.received','Fundraiser request acknowledged','We\'ve received your fundraiser request','<p style=\"font-size: 14px; line-height: 1.6;\">Hi {{ name }},</p>\n<p style=\"font-size: 14px; line-height: 1.6;\">Thanks for submitting \"{{ title }}\" — our team will review it and get back to you shortly.</p>','[\"name\", \"title\", \"org_name\"]',1,0,'2026-08-03 04:31:01','2026-08-03 04:31:01'),(17,'fundraiser.approved','Fundraiser request approved','Your fundraiser request has been approved','<p style=\"font-size: 14px; line-height: 1.6;\">Hi {{ name }},</p>\n<p style=\"font-size: 14px; line-height: 1.6;\">Good news — \"{{ title }}\" has been approved. We\'ve created a draft campaign for it in the admin, and our team will be in touch about publishing it.</p>','[\"name\", \"title\", \"org_name\"]',1,0,'2026-08-03 04:31:01','2026-08-03 04:31:01'),(18,'fundraiser.rejected','Fundraiser request rejected','Update on your fundraiser request','<p style=\"font-size: 14px; line-height: 1.6;\">Hi {{ name }},</p>\n<p style=\"font-size: 14px; line-height: 1.6;\">After review, we\'re not able to move forward with \"{{ title }}\" at this time. Reason: {{ reason }}</p>','[\"name\", \"title\", \"reason\", \"org_name\"]',1,0,'2026-08-03 04:31:01','2026-08-03 04:31:01'),(19,'fundraiser.new_request','New fundraiser request (admin)','New fundraiser request: {{ title }}','<p style=\"font-size: 14px; line-height: 1.6;\">{{ name }} submitted a new fundraiser request \"{{ title }}\" with a goal of ₹{{ goal_amount }}. Review it in the admin panel.</p>','[\"name\", \"title\", \"goal_amount\", \"org_name\"]',1,0,'2026-08-03 04:31:01','2026-08-03 04:31:01'),(20,'contact.new_message','New contact form message (admin)','New contact form message: {{ subject_line }}','<p style=\"font-size: 14px; line-height: 1.6;\"><strong>{{ name }}</strong> ({{ email }}) sent:</p>\n<p style=\"font-size: 14px; line-height: 1.6;\">{{ message }}</p>','[\"name\", \"email\", \"subject_line\", \"message\", \"org_name\"]',1,0,'2026-08-03 04:31:01','2026-08-03 04:31:01'),(21,'newsletter.confirm','Newsletter double opt-in','Confirm your subscription to {{ org_name }}','<p style=\"font-size: 14px; line-height: 1.6;\">Thanks for subscribing! Please confirm your email address to start receiving updates.</p>\n<p style=\"font-size: 14px; line-height: 1.6;\"><a href=\"{{ confirm_url }}\">Confirm my subscription</a></p>','[\"confirm_url\", \"org_name\"]',1,0,'2026-08-03 04:31:01','2026-08-03 04:31:01'),(22,'reports.monthly_summary','Monthly summary (admin)','{{ org_name }} — summary for {{ month }}','<h1 style=\"font-size: 18px; margin: 0 0 16px;\">Summary for {{ month }}</h1>\n<p style=\"font-size: 14px; line-height: 1.6;\">Total raised: <strong>₹{{ total }}</strong> from {{ donor_count }} donor(s).</p>\n<p style=\"font-size: 14px; line-height: 1.6;\">New recurring donors: {{ new_recurring_donors }}. Cancelled subscriptions: {{ churned_subscriptions }}.</p>\n<p style=\"font-size: 14px; line-height: 1.6;\">Top campaign: {{ top_campaign }}.</p>\n<p style=\"font-size: 14px; line-height: 1.6;\">{{ attention_summary }}</p>','[\"month\", \"total\", \"donor_count\", \"new_recurring_donors\", \"churned_subscriptions\", \"top_campaign\", \"attention_summary\", \"org_name\"]',1,0,'2026-08-03 04:31:01','2026-08-03 04:31:01');
